CREATE TABLE IF NOT EXISTS role ( id VARCHAR(200) NOT NULL, name VARCHAR(200) NOT NULL, description VARCHAR(400) NULL, privileges ${JSON_TYPE} NOT NULL, roles ${JSON_TYPE} NOT NULL, read_only BOOLEAN NOT NULL, version INT NOT NULL DEFAULT 1,
